import React from 'react';
import { Job } from '../types/job';
import PdfJsViewer from './PdfJsViewer';
import './PdfViewerModal.css';
import './PdfJsViewer.css';

interface PdfViewerModalProps {
  job: Job | null;
  isOpen: boolean;
  onClose: () => void;
}

const PdfViewerModal: React.FC<PdfViewerModalProps> = ({ job, isOpen, onClose }) => {
  if (!isOpen || !job) return null;

  const handleBackdropClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (e.target === e.currentTarget) {
      onClose();
    }
  };

  const handleApplyClick = () => {
    window.open(job.url, '_blank', 'noopener,noreferrer');
  };

  return (
    <div className="pdf-viewer-modal-backdrop" onClick={handleBackdropClick}>
      <div className="pdf-viewer-modal">
        <div className="pdf-viewer-header">
          <div className="pdf-viewer-title">
            <h2>{job.title}</h2>
            <p className="company-name">{job.company_korean_name || job.company_name}</p>
          </div>
          <button className="close-button" onClick={onClose}>
            <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M18 6L6 18" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
              <path d="M6 6L18 18" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
          </button>
        </div>
        
        <div className="pdf-viewer-content">
          <PdfJsViewer pdfUrl={`/jobs/api/jobs/${job.id}/pdf`} />
        </div>
        
        <div className="pdf-viewer-footer">
          <button className="apply-button" onClick={handleApplyClick}>
            지원하기
          </button>
        </div>
      </div>
    </div>
  );
};

export default PdfViewerModal;