import React from 'react';
import { Job } from '../types/job';
import { format, parseISO } from 'date-fns';
import { getCompanyLogoUrl } from '../utils/companyLogos';
import './JobCard.css';

interface JobCardProps {
  job: Job;
  onClick: (job: Job) => void;
  role?: string;
}

const JobCard: React.FC<JobCardProps> = ({ job, onClick }) => {
  const formatDate = (dateString: string | null) => {
    if (!dateString) return '상시채용';
    try {
      return format(parseISO(dateString), 'yyyy.MM.dd');
    } catch {
      return dateString;
    }
  };

  const getExperienceText = () => {
    if (job.experience_level === '신입') return '신입';
    if (job.experience_level === '경력') {
      if (job.experience_years_min && job.experience_years_max) {
        return `경력 ${job.experience_years_min}~${job.experience_years_max}년`;
      } else if (job.experience_years_min) {
        return `경력 ${job.experience_years_min}년 이상`;
      }
      return '경력';
    }
    return job.experience_level || '경력무관';
  };

  return (
    <div className="job-card" onClick={() => onClick(job)}>
      <div className="job-card-header">
        <div className="company-info">
          {(job.company_logo || getCompanyLogoUrl(job.company_name)) ? (
            <img 
              src={job.company_logo || getCompanyLogoUrl(job.company_name)} 
              alt={job.company_name} 
              className="company-logo" 
              onError={(e) => {
                e.currentTarget.style.display = 'none';
              }}
            />
          ) : (
            <div className="company-logo-placeholder">
              {job.company_name.charAt(0).toUpperCase()}
            </div>
          )}
          <div className="company-name">
            {job.company_korean_name || job.company_name}
          </div>
        </div>
        <div className="view-count">
          <svg className="view-icon" width="16" height="16" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M12 5C7 5 2.73 8.11 1 12.5C2.73 16.89 7 20 12 20C17 20 21.27 16.89 23 12.5C21.27 8.11 17 5 12 5ZM12 17.5C9.24 17.5 7 15.26 7 12.5C7 9.74 9.24 7.5 12 7.5C14.76 7.5 17 9.74 17 12.5C17 15.26 14.76 17.5 12 17.5ZM12 9.5C10.34 9.5 9 10.84 9 12.5C9 14.16 10.34 15.5 12 15.5C13.66 15.5 15 14.16 15 12.5C15 10.84 13.66 9.5 12 9.5Z" fill="currentColor"/>
          </svg>
          <span>{job.view_count || 0}</span>
        </div>
      </div>
      
      <h3 className="job-title">{job.title}</h3>
      
      <div className="job-meta">
        <div className="meta-row">
          <span className="meta-label">경력</span>
          <span className="meta-value">{getExperienceText()}</span>
        </div>
        
        <div className="meta-row">
          <span className="meta-label">정규직</span>
          <span className="meta-value">{job.job_type || '정규직'}</span>
        </div>
        
        {job.education_level && (
          <div className="meta-row">
            <span className="meta-label">학력</span>
            <span className="meta-value">{job.education_level}</span>
          </div>
        )}
        
        <div className="meta-row">
          <span className="meta-label">지역</span>
          <span className="meta-value">{job.location || '서울'}</span>
        </div>
      </div>
      
      <div className="job-footer">
        <span className="deadline">
          마감일: {formatDate(job.deadline)}
        </span>
        {job.is_remote && <span className="remote-badge">재택근무</span>}
      </div>
    </div>
  );
};

export default JobCard;