import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { jobApi } from '../api/jobApi';
import { Company } from '../types/job';
import { getCompanyLogoUrl } from '../utils/companyLogos';
import './CompanyList.css';

const CompanyList: React.FC = () => {
  const navigate = useNavigate();
  const [companies, setCompanies] = useState<Company[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadCompanies();
  }, []);

  const loadCompanies = async () => {
    try {
      const response = await jobApi.getCompanies();
      if (response.data && response.data.data && Array.isArray(response.data.data)) {
        setCompanies(response.data.data);
      } else {
        console.error('Invalid data format:', response);
        setCompanies([]);
      }
    } catch (error) {
      console.error('Failed to load companies:', error);
      setCompanies([]);
    } finally {
      setLoading(false);
    }
  };

  const handleCompanyClick = (company: Company) => {
    navigate(`/jobs?company=${encodeURIComponent(company.name)}`);
  };

  if (loading) {
    return <div className="loading">로딩중...</div>;
  }

  return (
    <div className="company-list-container">
      <h1>회사별 채용공고</h1>
      <div className="company-grid">
        {companies && companies.length > 0 ? companies.map(company => (
          <div 
            key={company.id} 
            className="company-card"
            onClick={() => handleCompanyClick(company)}
          >
            {(company.logo_url || getCompanyLogoUrl(company.name)) ? (
              <img 
                src={company.logo_url || getCompanyLogoUrl(company.name)} 
                alt={company.name} 
                className="company-logo"
                onError={(e) => {
                  e.currentTarget.style.display = 'none';
                }}
              />
            ) : (
              <div className="company-logo-placeholder">
                {company.name.charAt(0).toUpperCase()}
              </div>
            )}
            <h3>{company.korean_name || company.name}</h3>
            <p className="job-count">
              채용중 <strong>{company.active_jobs}</strong>건
            </p>
          </div>
        )) : (
          <div className="no-companies">등록된 회사가 없습니다.</div>
        )}
      </div>
    </div>
  );
};

export default CompanyList;