import React, { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import { jobApi } from '../api/jobApi';
import { Job, Filters } from '../types/job';
import JobCard from './JobCard';
import PdfViewerModal from './PdfViewerModal';
import './JobList.css';

const JobList: React.FC = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  
  const [jobs, setJobs] = useState<Job[]>([]);
  const [loading, setLoading] = useState(true);
  const [filters, setFilters] = useState<Filters | null>(null);
  const [totalJobs, setTotalJobs] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  
  // PDF 모달 상태
  const [selectedJob, setSelectedJob] = useState<Job | null>(null);
  const [isPdfModalOpen, setIsPdfModalOpen] = useState(false);

  // 필터 상태
  const [selectedCompany, setSelectedCompany] = useState(searchParams.get('company') || '');
  const [selectedJobType, setSelectedJobType] = useState(searchParams.get('job_type') || '');
  const [selectedExperience, setSelectedExperience] = useState(searchParams.get('experience_level') || '');
  const [selectedLocation, setSelectedLocation] = useState(searchParams.get('location') || '');
  const [selectedEducation, setSelectedEducation] = useState(searchParams.get('education_level') || '');
  const [searchQuery, setSearchQuery] = useState(searchParams.get('search') || '');

  useEffect(() => {
    loadFilters();
  }, []);

  useEffect(() => {
    loadJobs();
  }, [searchParams]);

  const loadFilters = async () => {
    try {
      const response = await jobApi.getFilters();
      // API 응답 형식에 따라 처리
      const filterData = response.data.data || response.data;
      if (filterData) {
        setFilters(filterData);
      }
    } catch (error) {
      console.error('Failed to load filters:', error);
    }
  };

  const loadJobs = async () => {
    setLoading(true);
    try {
      const params = {
        company: searchParams.get('company') || undefined,
        job_type: searchParams.get('job_type') || undefined,
        experience_level: searchParams.get('experience_level') || undefined,
        location: searchParams.get('location') || undefined,
        education_level: searchParams.get('education_level') || undefined,
        search: searchParams.get('search') || undefined,
        page: parseInt(searchParams.get('page') || '1'),
        limit: 20
      };

      const response = await jobApi.getJobs(params);
      // 안전한 데이터 설정
      setJobs(Array.isArray(response.data.jobs) ? response.data.jobs : []);
      setTotalJobs(response.data.pagination?.total || 0);
      setCurrentPage(response.data.pagination?.page || 1);
      setTotalPages(response.data.pagination?.pages || 1);
    } catch (error) {
      console.error('Failed to load jobs:', error);
    } finally {
      setLoading(false);
    }
  };

  const updateFilters = () => {
    const params = new URLSearchParams();
    if (selectedCompany) params.set('company', selectedCompany);
    if (selectedJobType) params.set('job_type', selectedJobType);
    if (selectedExperience) params.set('experience_level', selectedExperience);
    if (selectedLocation) params.set('location', selectedLocation);
    if (selectedEducation) params.set('education_level', selectedEducation);
    if (searchQuery) params.set('search', searchQuery);
    params.set('page', '1');
    
    setSearchParams(params);
  };

  const handlePageChange = (page: number) => {
    const params = new URLSearchParams(searchParams);
    params.set('page', page.toString());
    setSearchParams(params);
  };

  const handleJobClick = (job: Job) => {
    setSelectedJob(job);
    setIsPdfModalOpen(true);
    
    // 조회수 증가 API 호출
    jobApi.trackJobView(job.id).catch(console.error);
  };
  
  const handleClosePdfModal = () => {
    setIsPdfModalOpen(false);
    setSelectedJob(null);
  };

  const clearFilters = () => {
    setSelectedCompany('');
    setSelectedJobType('');
    setSelectedExperience('');
    setSelectedLocation('');
    setSelectedEducation('');
    setSearchQuery('');
    setSearchParams(new URLSearchParams());
  };

  return (
    <div className="job-list-container">
      <div className="filters-section">
        <h2>채용공고 검색</h2>
        
        <div className="search-box">
          <input
            type="text"
            placeholder="직무, 회사, 키워드 검색"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && updateFilters()}
          />
          <button onClick={updateFilters}>검색</button>
        </div>

        <div className="filters">
          <div className="filter-group">
            <label>고용형태</label>
            <select 
              value={selectedJobType} 
              onChange={(e) => setSelectedJobType(e.target.value)}
            >
              <option value="">전체</option>
              {filters?.job_types && Array.isArray(filters.job_types) && filters.job_types.map(type => (
                <option key={type} value={type}>{type}</option>
              ))}
            </select>
          </div>

          <div className="filter-group">
            <label>경력</label>
            <select 
              value={selectedExperience} 
              onChange={(e) => setSelectedExperience(e.target.value)}
            >
              <option value="">전체</option>
              {filters?.experience_levels && Array.isArray(filters.experience_levels) && filters.experience_levels.map(level => (
                <option key={level} value={level}>{level}</option>
              ))}
            </select>
          </div>

          <div className="filter-group">
            <label>학력</label>
            <select 
              value={selectedEducation} 
              onChange={(e) => setSelectedEducation(e.target.value)}
            >
              <option value="">전체</option>
              {filters?.education_levels && Array.isArray(filters.education_levels) && filters.education_levels.map(edu => (
                <option key={edu} value={edu}>{edu}</option>
              ))}
            </select>
          </div>

          <div className="filter-group">
            <label>지역</label>
            <select 
              value={selectedLocation} 
              onChange={(e) => setSelectedLocation(e.target.value)}
            >
              <option value="">전체</option>
              {filters?.locations && Array.isArray(filters.locations) && filters.locations.map(loc => (
                <option key={loc} value={loc}>{loc}</option>
              ))}
            </select>
          </div>

          <div className="filter-actions">
            <button onClick={updateFilters} className="apply-btn">적용</button>
            <button onClick={clearFilters} className="clear-btn">초기화</button>
          </div>
        </div>
      </div>

      <div className="jobs-section">
        <div className="jobs-header">
          <h3>전체 {totalJobs}개</h3>
        </div>

        {loading ? (
          <div className="loading">로딩중...</div>
        ) : (
          <>
            <div className="job-grid">
              {jobs && Array.isArray(jobs) && jobs.map(job => (
                <JobCard key={job.id} job={job} onClick={handleJobClick} />
              ))}
            </div>

            {totalPages > 1 && (
              <div className="pagination">
                <button 
                  onClick={() => handlePageChange(currentPage - 1)}
                  disabled={currentPage === 1}
                >
                  이전
                </button>
                
                <span className="page-info">
                  {currentPage} / {totalPages}
                </span>
                
                <button 
                  onClick={() => handlePageChange(currentPage + 1)}
                  disabled={currentPage === totalPages}
                >
                  다음
                </button>
              </div>
            )}
          </>
        )}
      </div>
      
      {/* PDF 뷰어 모달 */}
      <PdfViewerModal
        job={selectedJob}
        isOpen={isPdfModalOpen}
        onClose={handleClosePdfModal}
      />
    </div>
  );
};

export default JobList;