import axios from 'axios';
import { Company, JobsResponse, JobDetail, Filters } from '../types/job';

// API URL 설정 - 상대 경로 사용
const API_URL = process.env.REACT_APP_API_URL || '/jobs/api';

const api = axios.create({
  baseURL: API_URL,
});

interface ApiResponse<T> {
  success: boolean;
  data: T;
}

export const jobApi = {
  // 회사 목록 조회
  getCompanies: () => 
    api.get<ApiResponse<Company[]>>('/companies'),

  // 채용공고 목록 조회
  getJobs: (params: {
    company?: string;
    job_type?: string;
    experience_level?: string;
    location?: string;
    education_level?: string;
    search?: string;
    page?: number;
    limit?: number;
  }) => 
    api.get<JobsResponse>('/jobs', { params }),

  // 채용공고 상세 조회
  getJobDetail: (id: number) => 
    api.get<ApiResponse<JobDetail>>(`/jobs/${id}`),

  // 필터 옵션 조회
  getFilters: () => 
    api.get<ApiResponse<Filters>>('/filters'),
    
  // 채용공고 조회수 증가
  trackJobView: (id: number) =>
    api.post<ApiResponse<{ message: string }>>(`/jobs/${id}/view`),
};