// 회사 이름으로 로고 URL 가져오기
export const getCompanyLogoUrl = (companyName: string): string => {
  // 먼저 정확한 매칭 시도
  if (companyLogos[companyName]) {
    return companyLogos[companyName];
  }
  
  // 대소문자 구분 없이 찾기
  const lowerName = companyName.toLowerCase();
  for (const [key, value] of Object.entries(companyLogos)) {
    if (key.toLowerCase() === lowerName) {
      return value;
    }
  }
  
  // 기본 로고 (회사 이름 첫 글자)
  return '';
};

// getCompanyLogo - JobCard와 CompanyList에서 사용
export const getCompanyLogo = (companyName: string): string => {
  // 한국어 회사명을 영문으로 매핑
  const mappedName = companyNameMap[companyName] || companyNameMap[companyName.toLowerCase()] || companyName;
  return getCompanyLogoUrl(mappedName) || '/jobs/logo192.png';
};